const Layout = () => {
  const { user, logout, isAuthenticated } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const { getTotalItems } = useCart();
  const location = useLocation();

  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [showLogoutModal, setShowLogoutModal] = useState(false);
  const [scrollProgress, setScrollProgress] = useState(0);

  const [isSidebarPinned, setIsSidebarPinned] = useState(() => {
    try { return localStorage.getItem('pawzzle_sidebar_pinned') === 'true'; } catch { return false; }
  });
  
  const [isHovered, setIsHovered] = useState(false);
  const sidebarCollapsed = !isSidebarPinned && !isHovered;

  const [expandedGroups, setExpandedGroups] = useState(() => {
    try { return JSON.parse(sessionStorage.getItem('pawzzle_nav_groups') || '{}'); } catch { return {}; }
  });

  useEffect(() => {
    const handleScroll = () => {
      const h = document.documentElement.scrollHeight - window.innerHeight;
      if (h > 0) setScrollProgress((window.pageYOffset / h) * 100);
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  useEffect(() => {
    document.body.style.overflow = isMobileMenuOpen ? 'hidden' : '';
    return () => { document.body.style.overflow = ''; };
  }, [isMobileMenuOpen]);

  const handleLogout = () => setShowLogoutModal(true);
  const confirmLogout = () => { logout(); setShowLogoutModal(false); };

  const toggleSidebar = useCallback(() => {
    setIsSidebarPinned(prev => {
      const next = !prev;
      try { localStorage.setItem('pawzzle_sidebar_pinned', next ? 'true' : 'false'); } catch { }
      return next;
    });
  }, []);

  const toggleGroup = useCallback((label) => {
    setExpandedGroups(prev => {
      const next = { ...prev, [label]: !prev[label] };
      try { sessionStorage.setItem('pawzzle_nav_groups', JSON.stringify(next)); } catch { }
      return next;
    });
  }, []);

  const menuItems = useMemo(() => {
    if (!user) return publicMenu;
    switch (user.role) {
      case 'customer': return customerMenu;
      case 'admin':
      case 'store_owner': return getAdminMenu(user);
      case 'super_admin': return superAdminMenu;
      case 'platform_admin': return superAdminMenu;
      case 'staff': return getStaffMenu(user);
      case 'supplier': return supplierMenu;
      default: return OPERATIONAL_ROLES.has(user.role) ? getStaffMenu(user) : publicMenu;
    }
  }, [user]);

  useEffect(() => {
    const currentPath = location.pathname;
    menuItems.forEach(item => {
      if (item.children) {
        const hasActive = item.children.some(c => currentPath === c.path || currentPath.startsWith(c.path + '/'));
        if (hasActive && !expandedGroups[item.label]) {
          setExpandedGroups(prev => {
            const next = { ...prev, [item.label]: true };
            try { sessionStorage.setItem('pawzzle_nav_groups', JSON.stringify(next)); } catch { }
            return next;
          });
        }
      }
    });
  }, [location.pathname, menuItems]);

  const isActivePath = (path) => location.pathname === path || location.pathname.startsWith(path + '/');
  const isGroupActive = (group) => group.children?.some(c => isActivePath(c.path));
  const isLandingPage = location.pathname === '/' && !isAuthenticated;
  const isCustomerUI = user?.role === 'customer';
  const isStoreOwnerUI = user?.role === 'store_owner' || user?.role === 'admin';
  const isPlatformAdminUI = PLATFORM_ADMIN_ROLES.has(user?.role);
  const isStaffUI = user?.role === 'staff' || OPERATIONAL_ROLES.has(user?.role);
  const isSupplierUI = user?.role === 'supplier';
  const isCompactShell = isCustomerUI || isPlatformAdminUI || isSupplierUI;
  const sidebarWidth = isPlatformAdminUI
    ? (sidebarCollapsed ? 'w-[68px]' : 'w-[248px]')
    : (isCustomerUI || isSupplierUI)
    ? (sidebarCollapsed ? 'w-[72px]' : 'w-[240px]')
    : (sidebarCollapsed ? 'w-[84px]' : 'w-[280px]');
  const contentPadding = isPlatformAdminUI
    ? (isSidebarPinned ? 'lg:pl-[248px]' : 'lg:pl-[68px]')
    : (isCustomerUI || isSupplierUI)
    ? (isSidebarPinned ? 'lg:pl-[240px]' : 'lg:pl-[72px]')
    : (isSidebarPinned ? 'lg:pl-[280px]' : 'lg:pl-[84px]');
  const headerOffset = isPlatformAdminUI
    ? (sidebarCollapsed ? 'lg:left-[68px]' : 'lg:left-[248px]')
    : (isCustomerUI || isSupplierUI)
    ? (sidebarCollapsed ? 'lg:left-[72px]' : 'lg:left-[240px]')
    : (sidebarCollapsed ? 'lg:left-[84px]' : 'lg:left-[280px]');
  const workspaceLabel = isPlatformAdminUI
    ? 'Platform Operations'
    : isStoreOwnerUI
      ? 'Store Operations'
      : isSupplierUI
        ? 'Supplier Workspace'
        : isStaffUI
          ? 'Staff Workspace'
          : isCustomerUI
            ? 'Customer Marketplace'
            : 'Pawzzle';

  const renderNavItems = (items, collapsed = false, onNav) => (
    <div className="space-y-2">
      {items.map((item, idx) => (
        item.children ? (
          <NavGroup
            key={item.label}
            group={item}
            expanded={!!expandedGroups[item.label]}
            onToggle={() => toggleGroup(item.label)}
            isActive={isGroupActive(item)}
            collapsed={collapsed}
            onNavigate={onNav}
          />
        ) : (
          <NavLink
            key={item.path || idx}
            item={item}
            isActive={isActivePath(item.path)}
            collapsed={collapsed}
            onClick={onNav}
          />
        )
      ))}
    </div>
  );

  const pendingProfessional = isProfessionalVerificationPending(user);
  if (pendingProfessional && location.pathname !== '/professional-verification') return <Navigate to="/professional-verification" replace />;
  if (pendingProfessional) return <><Outlet /><PasswordChangeModal /></>;

  return (
    <div className={`app-shell min-h-screen w-full max-w-full min-w-0 bg-neutral-50 dark:bg-slate-950 flex flex-col lg:flex-row transition-colors duration-300 ${isCustomerUI ? 'customer-ui-shell' : ''} ${isStaffUI ? 'staff-ui-shell' : ''} ${isStoreOwnerUI ? 'store-owner-ui-shell' : ''} ${isSupplierUI ? 'supplier-ui-shell' : ''} ${isPlatformAdminUI ? 'super-admin-ui-shell' : ''} ${isLandingPage ? '!bg-transparent' : ''}`}>
      
      {!isLandingPage && (
        <div className="fixed top-0 left-0 h-1 bg-gradient-to-r from-primary via-secondary to-primary z-[100] transition-all duration-300" 
             style={{ width: `${scrollProgress}%` }} />
      )}

      {!isLandingPage && (
        <aside 
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
          className={`hidden lg:flex fixed left-0 top-0 h-screen ${sidebarWidth} bg-white dark:bg-slate-900 border-r border-slate-100 dark:border-slate-800 z-[60] flex-col transition-all duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] shadow-2xl shadow-slate-900/5`}
        >
          <div className={`shrink-0 flex items-center ${sidebarCollapsed ? 'px-3 py-5 justify-center' : 'px-6 py-6'} transition-all duration-500`}>
            <Link to="/" className="flex items-center gap-5 group/logo">
              <div className="w-12 h-12 bg-primary rounded-[1.25rem] flex items-center justify-center shadow-strong group-hover/logo:scale-110 transition-transform duration-500">
                <img src="/images/logo.png" alt="Logo" className="w-7 h-7 object-contain brightness-0 invert" />
              </div>
              {!sidebarCollapsed && (
                <div className="flex flex-col animate-scale-in">
                  <span className="text-2xl font-black tracking-tighter text-neutral-900 uppercase leading-none">PAWZZLE</span>
                  <span className="text-[9px] font-black text-primary tracking-[0.4em] uppercase mt-1">Ecosystem</span>
                </div>
              )}
            </Link>
          </div>

          <nav className={`flex-1 overflow-y-auto no-scrollbar py-4 ${sidebarCollapsed ? 'px-3' : 'px-5'}`}>
            {renderNavItems(menuItems, sidebarCollapsed)}
          </nav>

          <div className={`shrink-0 border-t border-slate-50 py-4 space-y-1 ${sidebarCollapsed ? 'px-3' : 'px-5'}`}>
            <button onClick={toggleTheme} aria-label="Change color theme" className={`sidebar-nav-item !py-4 ${sidebarCollapsed ? 'justify-center px-0' : 'px-6'}`}>
              {theme === 'dark' ? <Sun className="h-5 w-5 text-amber-500" /> : <Moon className="h-5 w-5 text-slate-400" />}
              {!sidebarCollapsed && <span className="text-xs">Appearance</span>}
            </button>

            {user && (
              <button onClick={handleLogout} className={`flex items-center gap-5 px-6 py-4 rounded-[1.5rem] text-slate-400 hover:bg-rose-50 hover:text-rose-600 transition-all duration-300 w-full ${sidebarCollapsed ? 'justify-center px-0' : ''}`}>
                <LogOut className="h-5 w-5 shrink-0" />
                {!sidebarCollapsed && <span className="text-[10px] font-black uppercase tracking-widest truncate">Logout</span>}
              </button>
            )}

            <button onClick={toggleSidebar} aria-label={isSidebarPinned ? 'Collapse navigation' : 'Expand navigation'} className={`flex items-center gap-5 px-6 py-4 text-slate-200 hover:text-primary transition-all duration-300 w-full ${sidebarCollapsed ? 'justify-center px-0' : ''}`}>
              {isSidebarPinned ? <ChevronsLeft className="h-5 w-5 shrink-0" /> : <ChevronsRight className="h-5 w-5 shrink-0" />}
              {!sidebarCollapsed && <span className="text-[9px] font-black uppercase tracking-widest truncate">Locked</span>}
            </button>
          </div>
        </aside>
      )}

      <div className={`app-content-shell w-full max-w-full flex-1 flex flex-col min-w-0 ${isLandingPage ? '' : `${contentPadding} ${isCompactShell ? 'pt-14 lg:pt-16' : 'pt-16 lg:pt-20'}`} transition-all duration-500`}>
        {!isLandingPage && (
          <header className={`fixed top-0 left-0 ${headerOffset} right-0 z-50 glass-effect dark:border-b dark:border-slate-800 ${isCompactShell ? 'h-14 lg:h-16' : 'h-16 lg:h-20'} flex items-center px-4 sm:px-6 lg:px-8 justify-between transition-all duration-500 shadow-soft`}>
            <div className="flex items-center gap-6">
              <div className="lg:hidden">
                <button onClick={() => setIsMobileMenuOpen(true)} aria-label="Open navigation" className="p-2.5 bg-white shadow-soft rounded-xl text-neutral-800">
                  <Menu className="h-5 w-5" />
                </button>
              </div>
              <div className="hidden lg:flex items-center gap-4">
                 <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse" />
                 <span className="text-[11px] font-black text-neutral-400 uppercase tracking-[0.4em]">
                   {workspaceLabel}
                 </span>
              </div>
            </div>

            <div className="flex items-center gap-3 sm:gap-4">
              {user && (
                <>
                  <div className="flex items-center gap-3">
                    {user.role === 'customer' && (
                      <Link to="/cart" className="p-2.5 bg-white hover:bg-neutral-50 rounded-xl text-neutral-600 transition-all shadow-soft relative group">
                        <ShoppingCart size={19} className="group-hover:scale-110 transition-transform" />
                        {getTotalItems() > 0 && (
                          <span className="absolute -top-1 -right-1 w-6 h-6 bg-primary text-white text-[11px] font-black rounded-xl flex items-center justify-center shadow-lg animate-scale-in">
                            {getTotalItems()}
                          </span>
                        )}
                      </Link>
                    )}
                    <NotificationBell />
                  </div>

                  <Link to="/profile" className="flex items-center gap-3 p-1.5 bg-white rounded-xl border border-slate-50 hover:shadow-medium transition-all group">
                    <div className="flex flex-col text-right hidden sm:flex px-2">
                      <span className="text-sm font-black text-neutral-900 leading-none">{user.firstName}</span>
                      <span className="text-[10px] font-black text-primary uppercase tracking-[0.2em] mt-1.5">Verified</span>
                    </div>
                    <div className="w-9 h-9 sm:w-10 sm:h-10 rounded-xl bg-neutral-100 flex items-center justify-center text-primary font-bold overflow-hidden shadow-inner group-hover:scale-105 transition-transform shrink-0">
                      {user.avatar || user.profilePicture ? (
                        <img src={getImageUrl(user.avatar || user.profilePicture)} alt="" className="w-full h-full object-cover" />
                      ) : (
                        user.firstName ? user.firstName[0] : <User className="h-5 w-5" />
                      )}
                    </div>
                  </Link>
                </>
              )}
              {!user && (
                <Link to="/login" className="btn-primary">Access Portal</Link>
              )}
            </div>
          </header>
        )}

        <main className={`app-content-main w-full max-w-full min-w-0 flex-1 ${isCompactShell ? 'p-3 sm:p-4 lg:p-5' : 'p-4 sm:p-5 lg:p-8'} animate-fade-up ${isLandingPage ? 'p-0' : ''}`}>
          <div className={`app-page relative z-10 w-full max-w-full min-w-0 ${isCustomerUI ? 'customer-interface' : ''} ${isStaffUI ? 'staff-interface' : ''} ${isStoreOwnerUI ? 'store-owner-interface' : ''} ${isSupplierUI ? 'supplier-interface' : ''} ${isPlatformAdminUI ? 'super-admin-interface' : ''}`}>
            <Outlet />
          </div>
        </main>
      </div>

      <div className={`fixed inset-0 z-[150] lg:hidden transition-all duration-500 ${isMobileMenuOpen ? 'visible' : 'invisible'}`}>
        <div className={`absolute inset-0 bg-neutral-900/40 backdrop-blur-md transition-opacity duration-500 ${isMobileMenuOpen ? 'opacity-100' : 'opacity-0'}`}
             onClick={() => setIsMobileMenuOpen(false)} />
        <aside className={`absolute top-0 left-0 h-full ${isCustomerUI || isSupplierUI ? 'w-[260px]' : 'w-[280px]'} max-w-[88vw] bg-white dark:bg-slate-900 shadow-premium transition-transform duration-500 ease-[cubic-bezier(0.23,1,0.32,1)] flex flex-col ${isMobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
          <div className="shrink-0 p-5 flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-primary rounded-2xl flex items-center justify-center">
                <img src="/images/logo.png" alt="Logo" className="w-6 h-6 brightness-0 invert" />
              </div>
              <span className="font-black text-neutral-900 tracking-tighter uppercase text-xl">PAWZZLE</span>
            </div>
            <button onClick={() => setIsMobileMenuOpen(false)} aria-label="Close navigation" className="p-2.5 bg-neutral-50 rounded-xl text-neutral-400">
              <X className="h-5 w-5" />
            </button>
          </div>
          <nav className="flex-1 overflow-y-auto no-scrollbar p-4">
            {renderNavItems(menuItems, false, () => setIsMobileMenuOpen(false))}
          </nav>
          <div className="p-4 border-t border-slate-50 dark:border-slate-800 space-y-2">
            <button onClick={toggleTheme}
                    className="flex items-center gap-3 w-full p-3.5 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-300 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] active:scale-95 transition-all">
              {theme === 'dark' ? <Sun className="h-5 w-5 text-amber-400" /> : <Moon className="h-5 w-5" />}
              <span>{theme === 'dark' ? 'Light mode' : 'Dark mode'}</span>
            </button>
            {user && (
              <button onClick={() => { setIsMobileMenuOpen(false); handleLogout(); }}
                      className="flex items-center gap-3 w-full p-3.5 bg-rose-50 text-rose-600 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] active:scale-95 transition-all">
                <LogOut className="h-6 w-6" />
                <span>Logout</span>
              </button>
            )}
          </div>
        </aside>
      </div>

      <LogoutModal isOpen={showLogoutModal} onClose={() => setShowLogoutModal(false)} onConfirm={confirmLogout} />
      {user?.role === 'customer' && <div className="customer-floating-ui"><FloatingChatManager currentUser={user} /></div>}
      {isCareProfessional(user) && <BottomNavBar />}
      <PasswordChangeModal />
    </div>
  );
};

export default Layout;
